package com.crypto.laplace.execution;

import com.crypto.common.enums.PositionSide;
import com.crypto.laplace.model.*;
import com.crypto.laplace.persistence.*;
import com.crypto.scanner.config.ScannerProperties;
import com.crypto.laplace.service.StartupMarketUniverseService;
import java.math.*;import java.time.*;import java.util.*;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;

@Service @RequiredArgsConstructor
public class LaplacePaperExecutionService {
 public static final String STRATEGY="LAPLACE_KERNEL_REGRESSION_30M", VERSION="1.0";private static final int SCALE=12;
 private final LaplacePaperPositionRepository positions;private final LaplaceTradeEventRepository events;private final LaplaceExecutionPriceProvider prices;private final LaplacePnlCalculator pnl;private final ScannerProperties scanner;private final LaplaceTradeJsonlWriter writer;
 private final StartupMarketUniverseService universe;
 @Transactional public LaplacePaperPositionEntity open(LaplaceSignalResult signal,PositionSide side,String reversalId,String positionBefore){
  assertNoOpen(signal.symbol());var quote=prices.quote(signal.symbol());Instant requested=Instant.now();BigDecimal price=quote.value();BigDecimal notional=scanner.getPaper().getDefaultNotionalUsdt();if(notional==null||notional.signum()<=0)throw new IllegalStateException("INVALID_NOTIONAL");int leverage=scanner.getPaperCost().getLeverage();if(leverage<=0)throw new IllegalStateException("INVALID_NOTIONAL");BigDecimal margin=notional.divide(BigDecimal.valueOf(leverage),SCALE,RoundingMode.HALF_UP);BigDecimal quantity=notional.divide(price,SCALE,RoundingMode.DOWN);BigDecimal feeRate=scanner.getPaperCost().getTakerFeePct();
  if(quantity.signum()<=0)throw new IllegalStateException("INVALID_QUANTITY");BigDecimal fee=notional.multiply(feeRate).setScale(SCALE,RoundingMode.HALF_UP);String signalId=entryKey(signal,side);Instant now=Instant.now();
  var p=LaplacePaperPositionEntity.builder().id(UUID.randomUUID().toString()).strategy(STRATEGY).strategyVersion(VERSION).symbol(signal.symbol()).side(side).status(LaplacePositionStatus.OPEN).entrySignalId(signalId).entryCandleCloseTime(signal.signalCandleCloseTime()).entryTime(now).entrySignalClosePrice(BigDecimal.valueOf(signal.signalCandleClose())).entryExecutionPrice(price).margin(margin).quantity(quantity).notional(notional).leverage(leverage).entryFeeRate(feeRate).entryFee(fee).build();positions.saveAndFlush(p);
  Map<String,Object> payload=base(signal,"ENTRY",p,UUID.randomUUID().toString(),reversalId);payload.put("side",side);payload.put("positionBefore",positionBefore);payload.put("positionAfter",side);payload.put("entryReason",reversalId==null?"CONFIRMED_LAPLACE_"+side:"CONFIRMED_LAPLACE_REVERSAL");payload.put("signalDetectedAt",requested);payload.put("executionRequestedAt",requested);payload.put("executionTime",now);payload.put("executionPrice",price);payload.put("priceSource",quote.source());payload.put("margin",margin);payload.put("leverage",leverage);payload.put("notional",notional);payload.put("quantity",quantity);payload.put("entryFeeRate",feeRate);payload.put("entryFee",fee);saveEvent(payload,"ENTRY",reversalId,p);return p;
 }
 @Transactional public ReversalOutcome reverse(LaplaceSignalResult signal,LaplacePaperPositionEntity expected,PositionSide target,boolean openTarget){
  LaplacePaperPositionEntity p=singleOpenForUpdate(signal.symbol());if(!p.getId().equals(expected.getId()))throw new IllegalStateException("POSITION_STATE_CONFLICT");String exitSignalId=reversalKey(signal,target);if(p.getExitSignalId()!=null)throw new IllegalStateException("DUPLICATE_EXECUTION_BLOCKED");String reversalId=UUID.randomUUID().toString();Instant requested=Instant.now();var quote=prices.quote(signal.symbol());Instant now=Instant.now();BigDecimal exitFee=p.getQuantity().multiply(quote.value()).multiply(p.getEntryFeeRate()).setScale(SCALE,RoundingMode.HALF_UP);var result=pnl.calculate(p.getSide(),p.getEntryExecutionPrice(),quote.value(),p.getQuantity(),p.getEntryFee(),exitFee);
  p.setStatus(LaplacePositionStatus.CLOSED);p.setExitSignalId(exitSignalId);p.setExitTime(now);p.setExitExecutionPrice(quote.value());p.setExitFee(exitFee);p.setGrossPnl(result.gross());p.setGrossPnlPct(result.grossPct());p.setNetPnl(result.net());p.setNetPnlPct(result.netPct());p.setHoldingMinutes(Duration.between(p.getEntryTime(),now).toMinutes());p.setExitReason(openTarget?"OPPOSITE_CONFIRMED_LAPLACE_SIGNAL":"OPPOSITE_SIGNAL_OUTSIDE_ENTRY_UNIVERSE");positions.saveAndFlush(p);
  Map<String,Object> payload=base(signal,"EXIT",p,UUID.randomUUID().toString(),reversalId);payload.put("closedSide",p.getSide());payload.put("incomingSignal",target);payload.put("positionBefore",p.getSide());payload.put("positionAfter","FLAT");payload.put("exitReason",p.getExitReason());payload.put("entryTime",p.getEntryTime());payload.put("entrySignalClosePrice",p.getEntrySignalClosePrice());payload.put("entryExecutionPrice",p.getEntryExecutionPrice());payload.put("exitExecutionRequestedAt",requested);payload.put("exitTime",now);payload.put("exitExecutionPrice",quote.value());payload.put("priceSource",quote.source());payload.put("quantity",p.getQuantity());payload.put("notional",p.getNotional());payload.put("leverage",p.getLeverage());payload.put("grossPnl",p.getGrossPnl());payload.put("grossPnlPct",p.getGrossPnlPct());payload.put("entryFee",p.getEntryFee());payload.put("exitFeeRate",p.getEntryFeeRate());payload.put("exitFee",exitFee);payload.put("totalFee",p.getEntryFee().add(exitFee));payload.put("netPnl",p.getNetPnl());payload.put("netPnlPct",p.getNetPnlPct());payload.put("holdingMinutes",p.getHoldingMinutes());saveEvent(payload,"EXIT",reversalId,p);
  LaplacePaperPositionEntity opened=null;if(openTarget)try{opened=open(signal,target,reversalId,p.getSide().name());}catch(RuntimeException failure){throw new IllegalStateException("REVERSAL_OPEN_FAILED",failure);}return new ReversalOutcome(p,opened,reversalId);
 }
 private void assertNoOpen(String symbol){if(!positions.findOpenForUpdate(STRATEGY,symbol,LaplacePositionStatus.OPEN).isEmpty())throw new IllegalStateException("POSITION_STATE_CONFLICT");}
 public LaplacePaperPositionEntity singleOpenForUpdate(String symbol){List<LaplacePaperPositionEntity>x=positions.findOpenForUpdate(STRATEGY,symbol,LaplacePositionStatus.OPEN);if(x.size()!=1)throw new IllegalStateException("POSITION_STATE_CONFLICT");return x.getFirst();}
 private void saveEvent(Map<String,Object> payload,String type,String reversal,LaplacePaperPositionEntity p){String id=(String)payload.get("eventId");events.save(LaplaceTradeEventEntity.builder().eventId(id).eventType(type).reversalId(reversal).positionId(p.getId()).symbol(p.getSymbol()).payloadJson(writer.json(payload)).jsonlWritten(false).createdAt(Instant.now()).build());}
 private Map<String,Object> base(LaplaceSignalResult s,String type,LaplacePaperPositionEntity p,String eventId,String reversal){Map<String,Object>m=new LinkedHashMap<>();m.put("eventType",type);m.put("eventId",eventId);m.put("reversalId",reversal);m.put("strategy",STRATEGY);m.put("strategyVersion",VERSION);m.put("positionId",p.getId());m.put("symbol",s.symbol());m.put("timeframe",s.timeframe());m.put("kernel",s.kernel());m.put("bandwidth",s.bandwidth());m.put("source",s.source());m.put("repaint",s.repaint());m.put("startupUniverseSessionId",universe.sessionId());m.put("startupVolumeValue",universe.startupVolume(s.symbol()));m.put("minimumVolumeThreshold",universe.minimumVolumeThreshold());m.put("inStartupEntryUniverse",universe.symbols().contains(s.symbol()));m.put("signalCandleOpenTime",s.signalCandleOpenTime());m.put("signalCandleCloseTime",s.signalCandleCloseTime());m.put("signalCandleClose",s.signalCandleClose());m.put("regressionCurrent",s.regressionCurrent());m.put("regressionPrevious",s.regressionPrevious());m.put("regressionTwoBarsAgo",s.regressionTwoBarsAgo());m.put("currentSlope",s.currentSlope());m.put("previousSlope",s.previousSlope());m.put("currentAtr14",s.currentAtr14());m.put("previousAtr14",s.previousAtr14());m.put("currentNormalizedSlope",s.currentNormalizedSlope());m.put("previousNormalizedSlope",s.previousNormalizedSlope());m.put("entryThreshold",s.entryThreshold());m.put("reversalThreshold",s.reversalThreshold());m.put("confirmationBars",s.confirmationBars());m.put("entrySignal",s.entrySignal());m.put("strongReversalSignal",s.strongReversalSignal());return m;}
 public static String entryKey(LaplaceSignalResult s,PositionSide side){return STRATEGY+":"+s.symbol()+":"+s.signalCandleCloseTime()+":ENTRY:"+side;}public static String reversalKey(LaplaceSignalResult s,PositionSide side){return STRATEGY+":"+s.symbol()+":"+s.signalCandleCloseTime()+":REVERSAL:"+side;}
 public record ReversalOutcome(LaplacePaperPositionEntity closed,LaplacePaperPositionEntity opened,String reversalId){}
}
